<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\{FormCatalog,ProgrammeAccess,Administration,ReviewCategoryMap,AutoAllocator};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class FormCatalogController extends Controller {
 public function index(Request $r,ProgrammeAccess $a){$ids=$a->programmes($r->user(),'templates.manage');abort_unless($ids,403);return ['data'=>collect($ids)->map(fn($id)=>['programme_id'=>$id,'definition'=>FormCatalog::current($id)]),'programmes'=>DB::table('programmes')->whereIn('id',$ids)->get(['id','name'])];}
 public function publish(Request $r,int $programme,ProgrammeAccess $a){abort_unless($a->allows($r->user(),$programme,'templates.manage'),403);abort_unless(\App\Services\Administration::freshVerification($r->user(),$r->session()),423,'Verify your authenticator to publish a form.');
  $d=$r->validate(['stages'=>'required|array|min:1|max:30','stages.*'=>'required|string|max:100|distinct','categories'=>'required|array|min:1|max:40','categories.*.name'=>'required|string|max:100|distinct','categories.*.description'=>'required|string|max:1000','categories.*.family'=>'sometimes|string|max:100','categories.*.questions'=>'required|array|min:1|max:50','categories.*.questions.*.key'=>'required|regex:/^[a-z][a-z0-9_]{0,59}$/','categories.*.questions.*.label'=>'required|string|max:300','categories.*.questions.*.hint'=>'nullable|string|max:1000','categories.*.questions.*.required'=>'required|boolean','categories.*.questions.*.max'=>'required|integer|min:1|max:10000','categories.*.questions.*.type'=>'sometimes|in:text,textarea,number,select,multiselect,file','categories.*.questions.*.group'=>'sometimes|string|max:100','categories.*.questions.*.options'=>'sometimes|array|max:50','categories.*.questions.*.options.*'=>'required|string|max:150|distinct','categories.*.questions.*.stages'=>'sometimes|array','categories.*.questions.*.stages.*'=>'string']);
  foreach($d['categories'] as $c){abort_if(collect($c['questions'])->where('type','file')->count()>3,422,'A category can request up to three supporting documents.');abort_if(str_contains($c['name'],'.')||str_contains($c['name'],'*'),422,'Category names cannot contain dots or asterisks.');abort_if(count(array_unique(array_column($c['questions'],'key')))!==count($c['questions']),422,'Question keys must be unique in each category.');foreach($c['questions'] as $q){abort_if(in_array($q['type']??'', ['select','multiselect'],true)&&empty($q['options']),422,'Choice questions need options.');abort_if(array_diff($q['stages']??[],$d['stages']),422,'A question refers to an unknown stage.');}}
  return DB::transaction(function()use($r,$programme,$d){DB::table('programmes')->where('id',$programme)->lockForUpdate()->first();$revision=(DB::table('form_definitions')->where('programme_id',$programme)->max('revision')??0)+1;$previous=FormCatalog::current($programme);$schema=['mode'=>'online','version'=>'programme-'.$programme.'-v'.$revision,'stages'=>$d['stages'],'categories'=>collect($d['categories'])->mapWithKeys(fn($c)=>[$c['name']=>['description'=>$c['description'],'family'=>$c['family']??null,'questions'=>$c['questions']]])->all()];if(($previous['layout']??null)==='smart-v1'){$schema['layout']='smart-v1';$schema['core']=$previous['core'];};DB::table('form_definitions')->insert(['programme_id'=>$programme,'revision'=>$revision,'definition'=>json_encode($schema),'published_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);Administration::audit($r->user(),'application_form.published','programme',$programme,['version'=>$schema['version']],$programme);return ['definition'=>$schema];});
 }
 public function preferences(Request $r,ProgrammeAccess $a){$ids=$a->programmes($r->user(),'reviews.evaluate');abort_unless($ids,403);if($r->isMethod('GET'))return ['programmes'=>collect($ids)->map(fn($id)=>['id'=>$id,'name'=>DB::table('programmes')->where('id',$id)->value('name'),'categories'=>ReviewCategoryMap::summaries()]),'preferences'=>DB::table('reviewer_preferences')->where('user_id',$r->user()->id)->get(['programme_id','category'])];
  abort_if($r->user()->onboarding_completed_at,403,'Review preferences are locked after onboarding.');
  $d=$r->validate(['preferences'=>'required|array|min:1|max:200','preferences.*.programme_id'=>'required|integer','preferences.*.category'=>'required|string|max:100']);foreach($d['preferences'] as $p)abort_unless(in_array($p['programme_id'],$ids)&&in_array($p['category'],ReviewCategoryMap::summaries(),true),422,'Choose categories in your programme.');
  DB::transaction(function()use($r,$d){DB::table('users')->where('id',$r->user()->id)->lockForUpdate()->first();DB::table('reviewer_preferences')->where('user_id',$r->user()->id)->delete();foreach(collect($d['preferences'])->unique(fn($p)=>$p['programme_id'].':'.$p['category']) as $p)DB::table('reviewer_preferences')->insert(['user_id'=>$r->user()->id,...$p]);$r->user()->onboarding_completed_at=now();$r->user()->save();Administration::audit($r->user(),'reviewer.preferences_saved','user',$r->user()->id);});foreach($ids as $id)(new AutoAllocator)->assignReady($id);return ['message'=>'Preferences saved.'];
 }
}
